import { tool } from "ai"
import { createTwoFilesPatch } from "diff"
import { promises as fs } from "fs"
import * as path from "path"
import { z } from "zod"
import { assertFreshRead } from "@/tools/lib/file-time"
import {
	checkPermission,
	type Permission,
	PermissionDeniedError,
} from "@/agents/lib/permissions"
import { toolOutput } from "@/tools/lib/tool-output"
import { trimDiff } from "@/tools/lib/trim-diff"

/**
 * Check if a path is contained within a directory
 */
function isPathWithin(directory: string, filepath: string): boolean {
	const relative = path.relative(directory, filepath)
	return !relative.startsWith("..") && !path.isAbsolute(relative)
}

const description = `Writes a file to the local filesystem.

Usage:
- This tool will overwrite the existing file if there is one at the provided path.
- If this is an existing file, you MUST use the Read tool first to read the file's contents. This tool will fail if you did not read the file first.
- ALWAYS prefer editing existing files in the codebase. NEVER write new files unless explicitly required.
- NEVER proactively create documentation files (*.md) or README files. Only create documentation files if explicitly requested by the User.
- Only use emojis if the user explicitly requests it. Avoid writing emojis to files unless asked.
- Writing to paths outside the current working directory will include a warning.`

const inputSchema = z.object({
	filePath: z
		.string()
		.describe(
			"The path to the file to write (absolute or relative)",
		),
	content: z.string().describe("The content to write to the file"),
})

const outputSchema = toolOutput({
	pending: {
		filePath: z.string(),
		result: z.undefined(),
	},
	success: {
		filePath: z.string(),
		result: z.string(),
		content: z.string(),
		lineCount: z.number(),
		byteSize: z.number(),
		wasOverwrite: z.boolean(),
		diff: z.string().optional(),
		warning: z.string().optional(),
	},
	error: {
		filePath: z.string(),
	},
})

/**
 * Create a write tool with custom permission patterns.
 *
 * @param permissions - File path pattern to permission mapping, or a single permission for all files.
 *                     Patterns support wildcards (*) for matching.
 *                     Default requires approval for all writes.
 *
 * @example
 * // Allow writing all .ts files without approval
 * const tsWrite = createWriteTool({ "*.ts": "allow", "*": "ask" })
 *
 * @example
 * // Require approval for everything (default)
 * const strictWrite = createWriteTool({ "*": "ask" })
 *
 * @example
 * // Allow all writes without approval
 * const permissiveWrite = createWriteTool("allow")
 */
export function createWriteTool(
	permissions: Permission | Record<string, Permission> = "ask",
	opts: { scope?: string } = {},
) {
	const permissionPatterns =
		typeof permissions === "string" ? { "*": permissions } : permissions
	const scope = opts.scope ?? "global"

	return tool({
		description,
		inputSchema,
		outputSchema,
		needsApproval: ({ filePath }) => {
			const filepath = path.isAbsolute(filePath)
				? filePath
				: path.join(process.cwd(), filePath)

			const permission = checkPermission(filepath, permissionPatterns)

			if (permission === "deny") {
				throw new PermissionDeniedError("write", filepath)
			}

			// Return true if approval needed (ask), false if auto-allowed
			return permission === "ask"
		},
		toModelOutput: ({ output }) => {
			if (output.status === "error") {
				return {
					type: "error-text",
					value: `Error writing ${output.filePath}: ${output.error}`,
				}
			}
			if (output.status === "success") {
				if (output.warning) {
					return { type: "text", value: `⚠️ ${output.warning}` }
				}
				// Only the UI needs the diff for display purposes
				return { type: "text", value: "" }
			}
			throw new Error("Invalid output status in toModelOutput")
		},
		async *execute({ filePath, content }) {
			const filepath = path.isAbsolute(filePath)
				? filePath
				: path.join(process.cwd(), filePath)

			yield {
				status: "pending",
				message: `Writing file: ${filepath}`,
				filePath: filepath,
				result: undefined,
			}

			try {
				// Check if writing outside working directory
				const cwd = process.cwd()
				let warning: string | undefined
				if (!isPathWithin(cwd, filepath)) {
					warning = `Writing file outside working directory: ${filepath}`
				}

				// Create directory if it doesn't exist
				const dir = path.dirname(filepath)
				await fs.mkdir(dir, { recursive: true })

				// Check if file exists and get its content for diff
				let exists = false
				let previousContent = ""
				try {
					await fs.access(filepath)
					exists = true
					previousContent = await fs.readFile(filepath, "utf-8")
				} catch {
					// File doesn't exist
				}
				if (exists) {
					await assertFreshRead(scope, filepath)
				}

				// Write the file
				await fs.writeFile(filepath, content, "utf-8")

				// Calculate stats
				const lineCount = content.split("\n").length
				const byteSize = Buffer.byteLength(content, "utf-8")

				// Generate diff if overwriting
				let diff: string | undefined
				if (exists && previousContent !== content) {
					diff = trimDiff(
						createTwoFilesPatch(filepath, filepath, previousContent, content),
					)
				}

				const action = exists ? "overwritten" : "created"
				const message = `File ${action}: ${filepath} (${lineCount} lines, ${byteSize} bytes)`

				yield {
					status: "success",
					message,
					filePath: filepath,
					result: message,
					content,
					lineCount,
					byteSize,
					wasOverwrite: exists,
					diff,
					warning,
				}
			} catch (error) {
				yield {
					status: "error",
					message: `Failed to write ${filepath}`,
					filePath: filepath,
					error: error instanceof Error ? error.message : String(error),
				}
			}
		},
	})
}

/**
 * Default write tool with standard permissions.
 * All file writes require approval by default.
 */
export const writeTool = createWriteTool()

import { promises as fs } from "fs"

const reads = new Map<string, Map<string, number>>()
const seen = new Map<string, number>()
const MAX_SCOPES = 512
const MAX_AGE_MS = 6 * 60 * 60 * 1000

function bucket(scope: string): Map<string, number> {
	seen.set(scope, Date.now())
	const hit = reads.get(scope)
	if (hit) return hit
	const next = new Map<string, number>()
	reads.set(scope, next)
	cleanupReads()
	return next
}

export function cleanupReads(now = Date.now()): void {
	for (const [scope, at] of seen) {
		if (now - at <= MAX_AGE_MS) continue
		reads.delete(scope)
		seen.delete(scope)
	}
	if (reads.size <= MAX_SCOPES) return
	const sorted = Array.from(seen.entries()).sort((a, b) => a[1] - b[1])
	const drop = reads.size - MAX_SCOPES
	for (let i = 0; i < drop; i++) {
		const scope = sorted[i]?.[0]
		if (!scope) continue
		reads.delete(scope)
		seen.delete(scope)
	}
}

export async function markRead(scope: string, filepath: string): Promise<void> {
	const stat = await fs.stat(filepath)
	bucket(scope).set(filepath, stat.mtimeMs)
}

export async function assertFreshRead(scope: string, filepath: string): Promise<void> {
	const prev = bucket(scope).get(filepath)
	if (prev === undefined) {
		throw new Error(
			`File ${filepath} must be read before editing. Use the Read tool first.`,
		)
	}

	const stat = await fs.stat(filepath)
	if (stat.mtimeMs !== prev) {
		throw new Error(
			`File ${filepath} changed after it was read. Read it again before editing.`,
		)
	}
}

export function clearReads(scope?: string): void {
	if (scope) {
		reads.delete(scope)
		seen.delete(scope)
	} else {
		reads.clear()
		seen.clear()
	}
}

import { z } from "zod"

export const truncation = {
	truncated: z.boolean().optional(),
	truncationReason: z.string().optional(),
}

export const continuationHint = {
	continuationHint: z.string().optional(),
}

export const continuationOffset = {
	continuationOffset: z.number().optional(),
}

/**
 * Creates a union schema for tool output with pending, success, error, and optional streaming states.
 * This ensures consistent output structure across all tools.
 */
export function toolOutput<
	P extends Record<string, z.ZodTypeAny>,
	S extends Record<string, z.ZodTypeAny>,
	E extends Record<string, z.ZodTypeAny>,
	T extends Record<string, z.ZodTypeAny> | undefined = undefined,
>({
	pending,
	success,
	error,
	streaming,
}: {
	pending: P
	success: S
	error: E
	streaming?: T
}) {
	return z.union([
		z.object({
			status: z.literal("pending"),
			message: z.string(),
			...pending,
		}),
		z.object({
			status: z.literal("success"),
			message: z.string(),
			...success,
		}),
		z.object({
			status: z.literal("error"),
			message: z.string(),
			error: z.string(),
			...error,
		}),
		...(streaming
			? [
					z.object({
						status: z.literal("streaming"),
						message: z.string(),
						...streaming,
					}),
				]
			: []),
	])
}

/**
 * Trim common indentation from diff output for cleaner display.
 * Removes the minimum shared indentation from all diff content lines.
 */
export function trimDiff(diff: string): string {
	const lines = diff.split("\n")
	const contentLines = lines.filter(
		(line) =>
			(line.startsWith("+") || line.startsWith("-") || line.startsWith(" ")) &&
			!line.startsWith("---") &&
			!line.startsWith("+++"),
	)

	if (contentLines.length === 0) return diff

	let min = Infinity
	for (const line of contentLines) {
		const content = line.slice(1)
		if (content.trim().length > 0) {
			const match = content.match(/^(\s*)/)
			if (match) min = Math.min(min, match[1]!.length)
		}
	}

	if (min === Infinity || min === 0) return diff

	const trimmedLines = lines.map((line) => {
		if (
			(line.startsWith("+") || line.startsWith("-") || line.startsWith(" ")) &&
			!line.startsWith("---") &&
			!line.startsWith("+++")
		) {
			const prefix = line[0]
			const content = line.slice(1)
			return prefix + content.slice(min)
		}
		return line
	})

	return trimmedLines.join("\n")
}

/**
 * Permission level for a tool operation.
 * - "allow": Auto-approve, no user confirmation needed
 * - "deny": Block the operation entirely
 * - "ask": Require user approval before proceeding
 */
export type Permission = "allow" | "deny" | "ask"
export type PermissionPatterns = Record<string, Permission>
export type SupportedSubagentType =
	| "coding-agent"
	| "planning-agent"
	| "research-agent"

export interface AgentGovernanceConfig {
	taskPermissions?: PermissionPatterns
}

export const FILE_READ_COMMANDS: PermissionPatterns = {
	"ls*": "allow",
	"pwd*": "allow",
	"cat*": "allow",
	"head*": "allow",
	"tail*": "allow",
	"less*": "allow",
	"more*": "allow",
	"wc*": "allow",
	"file*": "allow",
	"stat*": "allow",
	"du*": "allow",
}

export const SEARCH_COMMANDS: PermissionPatterns = {
	"grep*": "allow",
	"rg*": "allow",
	"find*": "allow",
	"tree*": "allow",
	"which*": "allow",
	"whereis*": "allow",
}

export const TEXT_PROCESSING_COMMANDS: PermissionPatterns = {
	"sort*": "allow",
	"uniq*": "allow",
	"cut*": "allow",
	"diff*": "allow",
}

export const GIT_READ_COMMANDS: PermissionPatterns = {
	"git status*": "allow",
	"git diff*": "allow",
	"git log*": "allow",
	"git show*": "allow",
	"git branch": "allow",
	"git branch -v": "allow",
	"git branch -a": "allow",
	"git remote -v": "allow",
	"git blame*": "allow",
}

/** Dangerous commands that should always be denied */
export const DANGEROUS_COMMANDS: PermissionPatterns = {
	"rm -rf /*": "deny",
	"rm -rf /": "deny",
	"sudo rm*": "deny",
	"chmod 777*": "deny",
}

/** Full bash access with dangerous command guards. Requires user approval for unknown commands. */
export const FULL_BASH_PERMISSIONS: PermissionPatterns = {
	...FILE_READ_COMMANDS,
	...SEARCH_COMMANDS,
	...TEXT_PROCESSING_COMMANDS,
	...GIT_READ_COMMANDS,
	...DANGEROUS_COMMANDS,
	"*": "ask",
}

/** Read-only bash access. Denies any command not explicitly allowed. */
export const READONLY_BASH_PERMISSIONS: PermissionPatterns = {
	...FILE_READ_COMMANDS,
	...SEARCH_COMMANDS,
	...TEXT_PROCESSING_COMMANDS,
	...GIT_READ_COMMANDS,
	"*": "deny",
}

/**
 * Default subagent task permissions.
 * Known in-product agent types are auto-allowed; unknown task types require approval.
 */
export const DEFAULT_TASK_PERMISSIONS: PermissionPatterns = {
	"coding-agent": "allow",
	"planning-agent": "allow",
	"research-agent": "allow",
	"*": "ask",
}

/**
 * Merge permission maps where override patterns replace base patterns.
 */
export function mergePermissionPatterns(
	base: PermissionPatterns,
	override?: PermissionPatterns,
): PermissionPatterns {
	if (!override) {
		return { ...base }
	}
	return {
		...base,
		...override,
	}
}

/**
 * Match a value against a wildcard pattern.
 *
 * @param value - The string to test
 * @param pattern - The pattern with optional wildcards (*)
 *
 * @example
 * matchWildcard("ls -la", "ls*") // true
 * matchWildcard("git diff HEAD", "git diff*") // true
 * matchWildcard("rm -rf /", "*") // true
 */
export function matchWildcard(value: string, pattern: string): boolean {
	if (pattern === "*") return true

	// Escape regex special chars except *
	const escaped = pattern.replace(/[.+^${}()|[\]\\]/g, "\\$&")
	// Convert * to .* for regex matching
	const regex = new RegExp(`^${escaped.replace(/\*/g, ".*")}$`)
	return regex.test(value)
}

/**
 * Check permission for a value against a set of patterns.
 *
 * Patterns are checked from most specific to least specific:
 * 1. Exact matches (no wildcards) first
 * 2. Longer patterns before shorter ones
 * 3. Wildcard-only pattern (*) last
 *
 * @param value - The value to check (command, file path, etc.)
 * @param patterns - Pattern-to-permission mapping
 * @returns The permission level for this value
 *
 * @example
 * checkPermission("ls -la", { "ls*": "allow", "*": "ask" }) // "allow"
 * checkPermission("npm install", { "ls*": "allow", "*": "ask" }) // "ask"
 */
export function checkPermission(
	value: string,
	patterns: PermissionPatterns,
): Permission {
	// Sort patterns from most specific to least specific
	const sortedPatterns = Object.keys(patterns).sort((a, b) => {
		// Exact matches (no wildcards) come first
		const aHasWildcard = a.includes("*")
		const bHasWildcard = b.includes("*")
		if (!aHasWildcard && bHasWildcard) return -1
		if (aHasWildcard && !bHasWildcard) return 1

		// Wildcard-only pattern comes last
		if (a === "*") return 1
		if (b === "*") return -1

		// Longer patterns are more specific
		return b.length - a.length
	})

	for (const pattern of sortedPatterns) {
		if (matchWildcard(value, pattern)) {
			return patterns[pattern]!
		}
	}

	// Default to ask if no pattern matches
	return "ask"
}

export class PermissionDeniedError extends Error {
	constructor(
		public readonly operation: string,
		public readonly value: string,
	) {
		super(`Permission denied: ${operation} "${value}" is not allowed`)
		this.name = "PermissionDeniedError"
	}
}
